insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Fica instituído, no âmbito do órgão do Ministério da Justiça com atribuições para a execução da política de direitos humanos, o Programa Federal de Assistência a Vítimas e a Testemunhas Ameaçadas, a ser regulamentado por decreto do Poder Executivo.', '["Programa federal no Ministério da Justiça.","Regulamentado por decreto."]'::jsonb, '["Regulamentação por decreto do Poder Executivo."]'::jsonb, 'A União mantém um programa federal para vítimas e testemunhas ameaçadas.', '["Assertiva que exige lei complementar para regulamentar o programa federal erra: é por decreto."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
