insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz poderá, de ofício ou a requerimento das partes, conceder o perdão judicial e a consequente extinção da punibilidade ao acusado que, sendo primário, tenha colaborado efetiva e voluntariamente com a investigação e o processo criminal, desde que dessa colaboração tenha resultado a identificação dos demais coautores ou partícipes, a localização da vítima com a integridade física preservada ou a recuperação total ou parcial do produto do crime. A concessão levará em conta a personalidade do beneficiado e a natureza, circunstâncias, gravidade e repercussão social do fato.', '["Perdão judicial a acusado primário que colabora efetiva e voluntariamente.","Resultados: identificação de coautores, localização da vítima ou recuperação do produto.","Juiz considera personalidade e circunstâncias do fato."]'::jsonb, '["Exige RÉU PRIMÁRIO.","Os resultados do art. 13 são alternativos (qualquer um)."]'::jsonb, 'O réu primário que revela onde está a vítima sequestrada pode receber o perdão judicial.', '["Assertiva que concede o perdão judicial a réu reincidente erra: exige primariedade."]'::jsonb, '[{"termo":"Perdão judicial","significado":"Extinção da punibilidade concedida pelo juiz."}]'::jsonb, '["Art. 14"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-13'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O indiciado ou acusado que colaborar voluntariamente com a investigação policial e o processo criminal na identificação dos demais coautores ou partícipes, na localização da vítima com vida e na recuperação total ou parcial do produto do crime, no caso de condenação, terá pena reduzida de um a dois terços.', '["Colaboração voluntária na investigação e no processo.","Em caso de condenação, redução da pena de um a dois terços."]'::jsonb, '["Aqui a vítima deve ser localizada COM VIDA.","Redução de um a dois terços (não é perdão)."]'::jsonb, 'O réu que ajuda a localizar a vítima com vida e os cúmplices tem a pena reduzida.', '["Assertiva que exige a primariedade do colaborador no art. 14 erra: ela é do perdão judicial."]'::jsonb, '[]'::jsonb, '["Art. 13"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-14'
