insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Serão aplicadas em benefício do colaborador, na prisão ou fora dela, medidas especiais de segurança e proteção a sua integridade física, considerando ameaça ou coação eventual ou efetiva. Se estiver sob prisão temporária, preventiva ou em flagrante, será custodiado em dependência separada dos demais presos. Durante a instrução criminal, o juiz poderá determinar em seu favor as medidas do art. 8º. No regime fechado, o juiz poderá determinar medidas especiais para a segurança do colaborador em relação aos demais apenados.', '["Medidas especiais de segurança para o colaborador, preso ou solto.","Custódia em dependência separada.","Medidas cautelares do art. 8º durante a instrução.","Segurança no regime fechado."]'::jsonb, '["Colaborador preso cautelarmente fica separado dos demais presos."]'::jsonb, 'O colaborador preso em flagrante é mantido em cela separada.', '["Assertiva que mantém o colaborador junto com os demais presos erra."]'::jsonb, '[]'::jsonb, '["Art. 8º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-15'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 57 da Lei de Registros Públicos fica acrescido de um parágrafo: quando a alteração de nome for concedida em razão de fundada coação ou ameaça decorrente de colaboração com a apuração de crime, o juiz determinará a averbação no registro de origem da menção da existência de sentença concessiva da alteração, sem a averbação do nome alterado, que somente poderá ser feita mediante determinação posterior, considerando a cessação da coação ou ameaça.', '["Averbação da sentença sem o nome alterado.","O nome novo só é averbado depois, por ordem posterior."]'::jsonb, '["Altera a Lei de Registros Públicos; protege o sigilo do nome novo."]'::jsonb, 'O registro de nascimento mostra apenas que houve alteração, sem revelar o novo nome.', '["Assertiva que obriga a averbar o novo nome imediatamente erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-16'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O parágrafo único do art. 58 da Lei de Registros Públicos passa a admitir a substituição do prenome em razão de fundada coação ou ameaça decorrente da colaboração com a apuração de crime, por determinação, em sentença, do juiz competente, ouvido o Ministério Público.', '["Substituição do prenome por coação ou ameaça decorrente da colaboração.","Sentença do juiz, ouvido o MP."]'::jsonb, '["Altera a Lei de Registros Públicos."]'::jsonb, 'O juiz autoriza a troca do prenome da testemunha ameaçada.', '["Assertiva que dispensa a oitiva do Ministério Público na substituição erra."]'::jsonb, '[]'::jsonb, '["Art. 9º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-17'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O art. 18 da Lei de Registros Públicos passa a determinar que, ressalvado o disposto nos arts. 45, 57, §7º, e 95, parágrafo único, a certidão será lavrada independentemente de despacho judicial, devendo mencionar o livro de registro ou o documento arquivado no cartório.', '["Certidão independe de despacho judicial.","Ressalvados os casos de sigilo (arts. 45, 57, §7º, e 95)."]'::jsonb, '["Altera a Lei de Registros Públicos; as ressalvas protegem o sigilo."]'::jsonb, 'O cartório emite a certidão sem ordem do juiz, salvo nos casos ressalvados.', '["Assertiva que exige despacho judicial em toda certidão erra."]'::jsonb, '[]'::jsonb, '["Art. 16"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-18'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A União poderá utilizar estabelecimentos especialmente destinados ao cumprimento de pena de condenados que tenham prévia e voluntariamente prestado a colaboração de que trata a Lei. Para isso, poderá celebrar convênios com os Estados e o Distrito Federal.', '["Estabelecimentos específicos para condenados colaboradores.","Convênios com Estados e DF."]'::jsonb, '["Faculdade da União (''poderá'')."]'::jsonb, 'O colaborador condenado cumpre pena em unidade destinada a ele.', '["Assertiva que torna obrigatória a criação desses estabelecimentos erra: é faculdade."]'::jsonb, '[]'::jsonb, '["Art. 15"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-19'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Terão prioridade na tramitação o inquérito e o processo criminal em que figure indiciado, acusado, vítima ou réu colaboradores, vítima ou testemunha protegidas pelos programas. Qualquer que seja o rito, o juiz, após a citação, tomará antecipadamente o depoimento das pessoas incluídas nos programas, devendo justificar a eventual impossibilidade ou o possível prejuízo da oitiva antecipada para a instrução.', '["Prioridade de tramitação.","Depoimento antecipado após a citação, em qualquer rito."]'::jsonb, '["ATUALIZAÇÃO: incluído pela Lei nº 12.483, de 2011.","A oitiva antecipada é a regra; sua impossibilidade deve ser justificada."]'::jsonb, 'O juiz colhe logo após a citação o depoimento da testemunha protegida.', '["Assertiva que dispensa justificativa quando o juiz não faz a oitiva antecipada erra."]'::jsonb, '[]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'testemunhas' and u.unit_key = 'art-19-a'
